package com.smritisathi.app.core;
import android.content.*;
public class Session { private static final String P="smriti_auth"; private static SharedPreferences p(Context c){return c.getSharedPreferences(P,Context.MODE_PRIVATE);} public static void save(Context c,String token,String role,String id,String name,String lang){p(c).edit().putString("token",token).putString("role",role).putString("id",id).putString("name",name).putString("lang",lang).apply();} public static String token(Context c){return p(c).getString("token","");} public static String role(Context c){return p(c).getString("role","");} public static String id(Context c){return p(c).getString("id","");} public static String name(Context c){return p(c).getString("name","Friend");} public static String lang(Context c){return p(c).getString("lang","english");} public static void clear(Context c){p(c).edit().clear().apply();}}
